import { Cpu, Sparkles, WifiOff } from 'lucide-react'
import { cx } from '../../utils/ui.js'

/*
 * Honest label for AI-related content:
 *   nebius -> generated by the Nebius model (shows the model id)
 *   rules  -> deterministic Pockit rules (AI off, failed, or output rejected)
 *   other  -> offline demo data from the mock services
 */
export default function AiSourceBadge({ source, model, className }) {
  const meta =
    source === 'nebius'
      ? { icon: Sparkles, label: 'Nebius AI', cls: 'bg-violet-soft text-indigo', title: model ? `Generated by ${model}` : 'Generated by Nebius AI' }
      : source === 'rules'
        ? { icon: Cpu, label: 'Pockit rules', cls: 'bg-line/70 text-muted', title: 'Calculated with deterministic rules (AI not used)' }
        : { icon: WifiOff, label: 'Offline demo', cls: 'bg-warning/12 text-ink', title: 'Sample logic running in the browser' }
  const Icon = meta.icon
  return (
    <span title={meta.title} className={cx('inline-flex shrink-0 items-center gap-1 rounded-full px-2 py-0.5 text-[10px] font-semibold', meta.cls, className)}>
      <Icon className="size-3" />
      {meta.label}
    </span>
  )
}
